.stage { position: relative; min-height: 330px; padding: 16px; overflow: hidden; }
.panel { padding: 16px; display: grid; gap: 12px; align-content: start; }
.panel h2 { margin-bottom: 2px; }
.field { display: grid; gap: 6px; }
.field label, .field-label { color: var(--art-muted); font-size: 11px; font-weight: 600; }
select, input[type='range'] {
  width: 100%;
  min-height: 38px;
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius-sm);
  background: var(--art-surface-raised);
  padding: 8px 10px;
