input[type='range'] { padding: 0; accent-color: var(--art-accent); }
.button-row { display: flex; flex-wrap: wrap; gap: 7px; }
button {
  min-height: 36px;
  padding: 8px 11px;
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius-sm);
  background: transparent;
  color: var(--art-ink);
  font-size: 12px;
  font-weight: 550;
  transition: border-color 160ms ease, background 160ms ease, color 160ms ease;
}
button:hover:not(:disabled) { border-color: var(--art-accent); background: var(--art-accent-soft); }
button[data-active='true'], button.primary {
  border-color: transparent;
  background: var(--art-accent);
  color: #fff;
}
button[data-active='true']:hover, button.primary:hover { background: var(--art-accent-strong); }
