.field label, .field-label { color: var(--art-muted); font-size: 11px; font-weight: 600; }
select, input[type='range'] {
  width: 100%;
  min-height: 38px;
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius-sm);
  background: var(--art-surface-raised);
  padding: 8px 10px;
}
input[type='range'] { padding: 0; accent-color: var(--art-accent); }
.button-row { display: flex; flex-wrap: wrap; gap: 7px; }
button {
  min-height: 36px;
  padding: 8px 11px;
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius-sm);
  background: transparent;
  color: var(--art-ink);
  font-size: 12px;
  font-weight: 550;
  transition: border-color 160ms ease, background 160ms ease, color 160ms ease;
}
button:hover:not(:disabled) { border-color: var(--art-accent); background: var(--art-accent-soft); }
button[data-active='true'], button.primary {
  border-color: transparent;
  background: var(--art-accent);
  color: #fff;
}
button[data-active='true']:hover, button.primary:hover { background: var(--art-accent-strong); }
.metric-row { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; margin-bottom: 12px; }
.metric { padding: 0 0 8px; border-bottom: 1px solid var(--art-border); }
.metric strong { display: block; margin-bottom: 2px; font-family: var(--art-mono); font-size: 18px; font-weight: 600; letter-spacing: -0.02em; }
.metric span { color: var(--art-muted); font-size: 10px; }
.result {
  min-height: 46px;
  padding: 10px 11px;
  border: 1px solid var(--art-border);
  border-radius: var(--art-radius-sm);
  background: var(--art-surface-raised);
  color: var(--art-muted);
  font-family: var(--art-mono);
  font-size: 11px;
}
.result[data-tone='good'] { border-color: transparent; background: var(--art-good-soft); color: var(--art-good); }
.result[data-tone='warn'] { border-color: transparent; background: var(--art-warn-soft); color: var(--art-warn); }
.result[data-tone='bad'] { border-color: transparent; background: var(--art-bad-soft); color: var(--art-bad); }
.feedback {
  padding: 12px 13px;
  border-left: 3px solid var(--art-good);
  border-radius: var(--art-radius-sm);
  background: var(--art-good-soft);
  color: var(--art-good);
  font-weight: 600;
}
.timeline { padding: 12px 14px; display: flex; flex-wrap: wrap; gap: 12px; align-items: center; }
.step { display: inline-flex; align-items: center; gap: 6px; color: var(--art-muted); font-size: 11px; }
.step::before { content: ''; width: 7px; height: 7px; border: 1px solid var(--art-muted); border-radius: 50%; }
.step[data-state='done'] { color: var(--art-good); }
.step[data-state='done']::before { border-color: var(--art-good); background: var(--art-good); }
.step[data-state='current'] { color: var(--art-accent); }
.step[data-state='current']::before { border-color: var(--art-accent); background: var(--art-accent); box-shadow: 0 0 0 3px var(--art-accent-soft); }
.chart { display: block; width: 100%; height: 260px; border: 1px solid var(--art-border); border-radius: var(--art-radius-sm); background: var(--art-surface-raised); }
.motion-enter { animation: art-enter 240ms cubic-bezier(0.2, 0.8, 0.2, 1) both; }
.motion-highlight { animation: art-highlight 360ms cubic-bezier(0.2, 0.8, 0.2, 1); }
@keyframes art-enter { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: translateY(0); } }
@keyframes art-highlight { 0% { box-shadow: 0 0 0 0 var(--art-accent-soft); } 45% { box-shadow: 0 0 0 5px var(--art-accent-soft); } 100% { box-shadow: 0 0 0 0 var(--art-accent-soft); } }
@media (max-width: 780px) {
  .lab { padding: 16px; }
  .hero, .workspace { grid-template-columns: 1fr; }
  .stage { min-height: 290px; }
  .metric-row { gap: 8px; }
  .metric strong { font-size: 16px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 1ms !important; transition-duration: 1ms !important; scroll-behavior: auto !important; }
}

</style>
</head>
<body>
  <main class="lab">
    <header class="hero">
      <div>
        <p class="eyebrow">Guided experiment</p>
        <h1>Projectile prediction lab</h1>
        <p class="subtitle">Choose an angle, make a prediction, then launch. Compare what you expected with what actually happened.</p>
      </div>
      <span class="pill">Interactive model</span>
    </header>

    <nav class="timeline" aria-label="Experiment steps">
      <span class="step" data-state="current">1 Predict</span>
      <span class="step">2 Launch</span>
      <span class="step">3 Compare</span>
    </nav>

    <section class="workspace" aria-label="Projectile experiment">
      <div class="stage">
        <div class="metric-row" aria-label="Experiment constants">
          <div class="metric"><strong>45°</strong><span>Reference angle</span></div>
          <div class="metric"><strong>9.8</strong><span>Gravity · m/s²</span></div>
          <div class="metric"><strong>1.0</strong><span>Target distance · m</span></div>
        </div>
        <svg class="chart" viewBox="0 0 600 230" role="img" aria-label="Projectile trajectory preview">
          <defs>
            <linearGradient id="trajectory" x1="0" x2="1" y1="0" y2="0">
              <stop offset="0" stop-color="#5b5bd6" stop-opacity="0.2"/>
              <stop offset="1" stop-color="#5b5bd6" stop-opacity="0.95"/>
            </linearGradient>
          </defs>
          <path d="M38 190 H560" stroke="currentColor" stroke-opacity="0.18"/>
          <path d="M56 184 C160 38 302 38 474 184" fill="none" stroke="url(#trajectory)" stroke-width="4" stroke-linecap="round" stroke-dasharray="2 10"/>
          <circle cx="56" cy="184" r="7" fill="#5b5bd6"/>
          <circle cx="474" cy="184" r="13" fill="none" stroke="#16805c" stroke-width="3"/>
          <circle cx="474" cy="184" r="4" fill="#16805c"/>
          <text x="42" y="211" fill="currentColor" font-size="12">launch</text>
          <text x="447" y="211" fill="currentColor" font-size="12">target</text>
        </svg>
        <output id="result" class="result" role="status" aria-live="polite">Make a prediction, then launch.</output>
      </div>

      <aside class="panel" aria-label="Experiment controls">
        <h2>Controls</h2>
        <div class="field">
          <label for="angle">Launch angle</label>
          <select id="angle">
            <option value="30">30°</option>
            <option value="45" selected>45°</option>
            <option value="60">60°</option>
          </select>
        </div>
        <div class="field">
          <span class="field-label">Your prediction</span>
          <div class="button-row">
            <button id="predict-hit" type="button" aria-pressed="false">Predict hit</button>
            <button id="predict-miss" type="button" aria-pressed="false">Predict miss</button>
          </div>
        </div>
        <button id="launch" class="primary" type="button">Launch</button>
        <p class="subtitle">The model is deterministic. Your prediction is the only unknown.</p>
      </aside>
    </section>

    <aside class="feedback" id="feedback">Prediction matched: 45° reached the target.</aside>
    <footer class="timeline">
      <span class="step">Observe</span>
      <span class="step">Predict</span>
      <span class="step">Manipulate</span>
      <span class="step">Feedback</span>
    </footer>
  </main>

  <script>
/* Small, one-shot motion primitives. Inline this file into an Artifact; no imports. */
function reducedMotion() {
  return window.matchMedia('(prefers-reduced-motion: reduce)').matches
}

function beat(elements, { staggerMs = 70 } = {}) {
  const list = Array.from(elements)
  if (reducedMotion()) {
    for (const element of list) element.dataset.beat = 'done'
    return
  }
  for (const [index, element] of list.entries()) {
    element.classList.add('motion-enter')
    element.style.animationDelay = `${index * staggerMs}ms`
    element.addEventListener('animationend', () => { element.dataset.beat = 'done' }, { once: true })
  }
}

function highlight(element) {
  if (!element) return
  if (reducedMotion()) return
  element.classList.remove('motion-highlight')
  void element.offsetWidth
  element.classList.add('motion-highlight')
}

function tween({ from, to, duration = 420, update, done }) {
  if (reducedMotion()) {
    update(to)
    done?.()
    return () => {}
  }
  const start = performance.now()
  let frame = 0
  const step = (now) => {
    const progress = Math.min(1, (now - start) / duration)
    const eased = 1 - Math.pow(1 - progress, 3)
    update(from + (to - from) * eased)
    if (progress < 1) frame = requestAnimationFrame(step)
    else done?.()
  }
  frame = requestAnimationFrame(step)
  return () => cancelAnimationFrame(frame)
}

</script>
  <script>
    let angle = 45
    let prediction = null
    const result = document.getElementById('result')
    const angleInput = document.getElementById('angle')
    const hitButton = document.getElementById('predict-hit')
    const missButton = document.getElementById('predict-miss')

    function setPrediction(value) {
      prediction = value
      hitButton.dataset.active = String(value === true)
      missButton.dataset.active = String(value === false)
      hitButton.setAttribute('aria-pressed', String(value === true))
      missButton.setAttribute('aria-pressed', String(value === false))
      result.dataset.tone = ''
      result.textContent = `Prediction: ${value ? 'hit' : 'miss'}`
      highlight(result)
    }

    hitButton.addEventListener('click', () => { setPrediction(true) })
    missButton.addEventListener('click', () => { setPrediction(false) })
    angleInput.addEventListener('change', () => { angle = Number(angleInput.value) })
    document.getElementById('launch').addEventListener('click', () => {
      if (prediction === null) {
        result.dataset.tone = 'warn'
        result.textContent = 'Choose a prediction first'
        highlight(result)
        return
      }
      const actualHit = angle === 45
      const matched = prediction === actualHit
      result.dataset.tone = matched ? 'good' : 'warn'
      result.textContent = `Actual: ${actualHit ? 'hit' : 'miss'} — ${matched ? 'prediction matched' : 'prediction differed'}`
      for (const step of document.querySelectorAll('.timeline .step')) step.dataset.state = 'done'
      highlight(result)
      parent.postMessage({
        kind: 'artifact-action', artifactId: 'projectile-lab', revision: 1,
        action: 'shot.completed', payload: { angle, predictedHit: prediction, actualHit },
      }, '*')
    })

    beat(document.querySelectorAll('.hero, .workspace, .timeline'))
  </script>
</body>
</html>
